CREATE TABLE "c_Booking" ("id" BIGINT NOT NULL, "a_Booking_booked_at" TIMESTAMP NOT NULL, "a_Booking_status" TEXT NOT NULL, "r_TravelerBookings_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_TravelerBookings_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_TravelerBookings_source_id" IS NOT NULL));
CREATE TABLE "c_ItineraryItem" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_FlightSegment_flight_no" TEXT, "a_HotelStay_hotel_name" TEXT, "a_ItineraryItem_start_time" TIMESTAMP, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('FlightSegment','HotelStay','ItineraryItem')), CHECK ((dtype IN ('FlightSegment')) OR "a_FlightSegment_flight_no" IS NULL), CHECK (NOT (dtype IN ('FlightSegment')) OR "a_FlightSegment_flight_no" IS NOT NULL), CHECK ((dtype IN ('HotelStay')) OR "a_HotelStay_hotel_name" IS NULL), CHECK (NOT (dtype IN ('HotelStay')) OR "a_HotelStay_hotel_name" IS NOT NULL), CHECK ((dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "a_ItineraryItem_start_time" IS NULL), CHECK (NOT (dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "a_ItineraryItem_start_time" IS NOT NULL));
CREATE TABLE "c_Payment" ("id" BIGINT NOT NULL, "a_Payment_amount" NUMERIC NOT NULL, "r_BookingPayments_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_BookingPayments_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_BookingPayments_source_id" IS NOT NULL));
CREATE TABLE "c_Traveler" ("id" BIGINT NOT NULL, "a_Traveler_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_BookingItems" ("r_BookingItems_source_id" BIGINT NOT NULL, "r_BookingItems_target_id" BIGINT NOT NULL, "r_BookingItems_target_dtype" TEXT NOT NULL, PRIMARY KEY ("r_BookingItems_source_id", "r_BookingItems_target_id"), UNIQUE ("r_BookingItems_target_id"), CHECK ("r_BookingItems_target_dtype" IS NULL OR "r_BookingItems_target_dtype" IN ('FlightSegment','HotelStay','ItineraryItem')));
ALTER TABLE "c_Booking" ADD CONSTRAINT "fk_c_Booking_0" FOREIGN KEY ("r_TravelerBookings_source_id") REFERENCES "c_Traveler" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Payment" ADD CONSTRAINT "fk_c_Payment_0" FOREIGN KEY ("r_BookingPayments_source_id") REFERENCES "c_Booking" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_BookingItems" ADD CONSTRAINT "fk_l_BookingItems_0" FOREIGN KEY ("r_BookingItems_source_id") REFERENCES "c_Booking" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_BookingItems" ADD CONSTRAINT "fk_l_BookingItems_1" FOREIGN KEY ("r_BookingItems_target_id", "r_BookingItems_target_dtype") REFERENCES "c_ItineraryItem" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_BookingItems"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_ItineraryItem" t WHERE (t.dtype IN ('FlightSegment','HotelStay','ItineraryItem')) AND NOT EXISTS (SELECT 1 FROM "l_BookingItems" l WHERE l."r_BookingItems_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: BookingItems'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_BookingItems_target" AFTER INSERT OR UPDATE OR DELETE ON "c_ItineraryItem" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_BookingItems"();
CREATE CONSTRAINT TRIGGER "ct_BookingItems_link" AFTER INSERT OR UPDATE OR DELETE ON "l_BookingItems" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_BookingItems"();